insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a7100001-0001-4001-8001-000000000001', 'como-melhorar-qualidade-do-sono', 'Como melhorar a qualidade do sono', 'Guia prático para noites mais reparadoras: rotina, ambiente e hábitos baseados em evidências — sem promessas milagrosas.', '[{"type":"image","url":"/blog/categories/sono.svg","alt":"Capa: Como melhorar a qualidade do sono"},{"type":"heading","level":2,"text":"Introdução"},{"type":"paragraph","text":"Dormir bem não é luxo — é fundamento para energia, humor, imunidade e saúde metabólica. A qualidade do sono depende menos de truques isolados e mais de consistência em horários, ambiente e rituais de desaceleração."},{"type":"paragraph","text":"Pequenos ajustes sustentados por duas a três semanas costumam gerar diferença perceptível na disposição matinal e na capacidade de concentração ao longo do dia."},{"type":"heading","level":2,"text":"Benefícios"},{"type":"list","items":["Mais energia e foco durante o dia","Melhor regulação hormonal e apetite","Recuperação muscular e imunológica otimizada","Humor mais estável e menor irritabilidade"]},{"type":"heading","level":2,"text":"Como aplicar"},{"type":"list","items":["Defina horário fixo para deitar e acordar, inclusive nos fins de semana.","Reduza luz azul e telas 60 minutos antes de dormir.","Mantenha o quarto escuro, silencioso e entre 18–21 °C.","Evite cafeína após 14h e refeições pesadas até 2h antes de deitar.","Crie ritual noturno de 15 minutos: respiração, leitura leve ou alongamento."],"ordered":true},{"type":"heading","level":2,"text":"Erros comuns"},{"type":"list","items":["Usar a cama para trabalhar ou rolar redes sociais","Dormir compensando apenas nos fins de semana","Depender de álcool para induzir sono","Ignorar ronco intenso ou pausas na respiração noturna"]},{"type":"heading","level":2,"text":"Perguntas frequentes"},{"type":"faq","items":[{"question":"Quantas horas de sono são ideais?","answer":"A maioria dos adultos se beneficia de 7 a 9 horas por noite. O indicador principal é acordar com disposição, sem depender excessivamente de cafeína."},{"question":"Cochilos durante o dia atrapalham?","answer":"Cochilos curtos (20 minutos) antes das 15h podem ajudar. Cochilos longos ou tardios fragmentam o sono noturno."},{"question":"Quando procurar ajuda profissional?","answer":"Se insônia, sonolência diurna ou ronco persistirem por mais de três semanas, consulte um médico para investigar causas tratáveis."}]},{"type":"heading","level":2,"text":"Conclusão"},{"type":"paragraph","text":"Melhorar o sono é um processo gradual. Escolha um ou dois hábitos, pratique com consistência e ajuste conforme sua rotina real — resultados duradouros vêm da repetição, não da perfeição."},{"type":"heading","level":2,"text":"Continue no Clube Saúde & Bem"},{"type":"paragraph","html":"<p>Quer protocolos premium, biblioteca ampliada e acompanhamento contínuo? O <strong>Clube Saúde &amp; Bem</strong> reúne ferramentas avançadas e conteúdo exclusivo para acelerar sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'sono', 'Sono', 'Dra. Marina Alves', 'Medicina Preventiva', '9 min', '01 Jun 2026', true, false, '/blog/categories/sono.svg', 'Como melhorar a qualidade do sono | Guia Saúde & Bem', 'Guia prático para noites mais reparadoras: rotina, ambiente e hábitos baseados em evidências — sem promessas milagrosas.', 'como, melhorar, qualidade, do, sono, sono, saúde, bem-estar, saúde e bem', '/blog/categories/sono.svg', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a7100001-0001-4001-8001-000000000002', 'beneficios-caminhada-diaria', 'Benefícios da caminhada diária', 'Por que 20 a 30 minutos de caminhada por dia impactam coração, humor, metabolismo e longevidade — com evidência científica.', '[{"type":"image","url":"/blog/categories/emagrecimento.svg","alt":"Capa: Benefícios da caminhada diária"},{"type":"heading","level":2,"text":"Introdução"},{"type":"paragraph","text":"A caminhada é um dos exercícios mais acessíveis e subestimados da medicina preventiva. Não exige equipamento caro, é escalável para qualquer idade e gera benefícios mensuráveis em poucas semanas."},{"type":"paragraph","text":"Integrar caminhadas à rotina é uma das formas mais sustentáveis de cuidar da saúde cardiovascular, do peso corporal e do bem-estar mental."},{"type":"heading","level":2,"text":"Benefícios"},{"type":"list","items":["Melhora da saúde cardiovascular e pressão arterial","Controle de peso e sensibilidade à insulina","Redução de estresse e ansiedade leve","Fortalecimento de ossos e articulações com baixo impacto"]},{"type":"heading","level":2,"text":"Como aplicar"},{"type":"list","items":["Comece com 15 minutos em ritmo confortável e aumente gradualmente.","Meta inicial: 6.000 a 8.000 passos/dia; evolução para 8.000–10.000 conforme condicionamento.","Prefira horários fixos — manhã ou fim de tarde — para criar hábito.","Use tênis confortável e hidrate-se antes e depois.","Combine com música, podcast ou caminhada em dupla para manter consistência."],"ordered":true},{"type":"heading","level":2,"text":"Erros comuns"},{"type":"list","items":["Começar com volume ou intensidade excessivos","Caminhar apenas no fim de semana","Ignorar dor persistente em joelhos ou tornozelos","Substituir alimentação equilibrada apenas por caminhada"]},{"type":"heading","level":2,"text":"Perguntas frequentes"},{"type":"faq","items":[{"question":"Caminhada queima gordura?","answer":"Sim, especialmente em ritmo moderado prolongado. O maior benefício vem da consistência diária combinada com alimentação adequada."},{"question":"Qual ritmo é considerado moderado?","answer":"Você deve conseguir conversar com leve esforço. Se não conseguir falar, o ritmo está alto demais para manutenção diária."},{"question":"Chuva ou falta de tempo: o que fazer?","answer":"Caminhada indoor, subir escadas ou pausas ativas de 10 minutos somam ao longo do dia e mantêm o hábito."}]},{"type":"heading","level":2,"text":"Conclusão"},{"type":"paragraph","text":"A caminhada diária é investimento de alto retorno com baixo risco. Comece pequeno, seja constante e ajuste o volume conforme sua evolução."},{"type":"heading","level":2,"text":"Continue no Clube Saúde & Bem"},{"type":"paragraph","html":"<p>Quer protocolos premium, biblioteca ampliada e acompanhamento contínuo? O <strong>Clube Saúde &amp; Bem</strong> reúne ferramentas avançadas e conteúdo exclusivo para acelerar sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'emagrecimento', 'Atividade física', 'Dr. Rafael Costa', 'Nutrição Clínica', '7 min', '02 Jun 2026', true, false, '/blog/categories/emagrecimento.svg', 'Benefícios da caminhada diária | Guia Saúde & Bem', 'Por que 20 a 30 minutos de caminhada por dia impactam coração, humor, metabolismo e longevidade — com evidência científica.', 'beneficios, caminhada, diaria, emagrecimento, saúde, bem-estar, saúde e bem', '/blog/categories/emagrecimento.svg', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a7100001-0001-4001-8001-000000000003', 'como-reduzir-estresse-naturalmente', 'Como reduzir o estresse naturalmente', 'Estratégias práticas de respiração, rotina e estilo de vida para diminuir o estresse crônico sem depender apenas de estimulantes.', '[{"type":"image","url":"/blog/categories/longevidade.svg","alt":"Capa: Como reduzir o estresse naturalmente"},{"type":"heading","level":2,"text":"Introdução"},{"type":"paragraph","text":"Estresse faz parte da vida moderna, mas quando se torna crônico afeta sono, digestão, imunidade e saúde cardiovascular. A boa notícia: hábitos simples reduzem a resposta fisiológica ao estresse."},{"type":"paragraph","text":"O objetivo não é eliminar desafios — é construir resiliência para responder melhor a eles."},{"type":"heading","level":2,"text":"Benefícios"},{"type":"list","items":["Menor tensão muscular e dores relacionadas","Sono mais reparador e humor equilibrado","Melhor tomada de decisão sob pressão","Redução de marcadores inflamatórios associados ao estresse"]},{"type":"heading","level":2,"text":"Como aplicar"},{"type":"list","items":["Pratique respiração diafragmática 5 minutos, 2x ao dia.","Reserve blocos sem tela para pausas conscientes.","Mantenha movimento regular — caminhada já reduz cortisol.","Organize prioridades com lista simples de três tarefas essenciais/dia.","Durma 7–8 horas — privação amplifica estresse percebido."],"ordered":true},{"type":"heading","level":2,"text":"Erros comuns"},{"type":"list","items":["Usar álcool ou excesso de cafeína como válvula de escape","Trabalhar sem pausas por horas consecutivas","Ignorar sinais de esgotamento (burnout)","Buscar perfeição em todas as áreas simultaneamente"]},{"type":"heading","level":2,"text":"Perguntas frequentes"},{"type":"faq","items":[{"question":"Meditação é obrigatória?","answer":"Não. Respiração guiada, caminhada consciente ou journaling já trazem benefícios. Escolha a prática que você consegue manter."},{"question":"Suplementos calmantes funcionam?","answer":"Alguns podem ajudar pontualmente, mas não substituem sono, movimento e limites saudáveis. Consulte um profissional antes de usar."},{"question":"Quando o estresse exige ajuda médica?","answer":"Ansiedade incapacitante, ataques de pânico ou insônia persistente merecem avaliação com médico ou psicólogo."}]},{"type":"heading","level":2,"text":"Conclusão"},{"type":"paragraph","text":"Reduzir estresse é treino de consistência. Pequenas pausas diárias somam mais que um dia inteiro de spa esporádico."},{"type":"heading","level":2,"text":"Continue no Clube Saúde & Bem"},{"type":"paragraph","html":"<p>Quer protocolos premium, biblioteca ampliada e acompanhamento contínuo? O <strong>Clube Saúde &amp; Bem</strong> reúne ferramentas avançadas e conteúdo exclusivo para acelerar sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'longevidade', 'Bem-estar', 'Dra. Marina Alves', 'Medicina Preventiva', '8 min', '03 Jun 2026', false, false, '/blog/categories/longevidade.svg', 'Como reduzir o estresse naturalmente | Guia Saúde & Bem', 'Estratégias práticas de respiração, rotina e estilo de vida para diminuir o estresse crônico sem depender apenas de estimulantes.', 'como, reduzir, estresse, naturalmente, longevidade, saúde, bem-estar, saúde e bem', '/blog/categories/longevidade.svg', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a7100001-0001-4001-8001-000000000004', 'como-criar-habitos-saudaveis', 'Como criar hábitos saudáveis', 'Ciência comportamental aplicada: como instalar hábitos que duram com gatilhos, rotinas mínimas e recompensas realistas.', '[{"type":"image","url":"/blog/categories/longevidade.svg","alt":"Capa: Como criar hábitos saudáveis"},{"type":"heading","level":2,"text":"Introdução"},{"type":"paragraph","text":"Hábitos saudáveis não nascem da força de vontade isolada — nascem de sistemas. Quando o ambiente e a rotina facilitam a ação certa, a consistência deixa de depender de motivação diária."},{"type":"paragraph","text":"Começar pequeno e ancorar novos comportamentos em hábitos existentes aumenta drasticamente a taxa de sucesso."},{"type":"heading","level":2,"text":"Benefícios"},{"type":"list","items":["Resultados cumulativos sem extremismos","Menor fadiga de decisão no dia a dia","Maior autoconfiança e senso de controle","Base sólida para metas maiores de saúde"]},{"type":"heading","level":2,"text":"Como aplicar"},{"type":"list","items":["Escolha um hábito mínimo viável (ex.: 10 minutos de movimento).","Use habit stacking: após o café, beba um copo de água.","Deixe gatilhos visíveis — garrafa na mesa, tênis à porta.","Registre streaks simples em calendário ou app.","Revise semanalmente o que funcionou e ajuste um detalhe por vez."],"ordered":true},{"type":"heading","level":2,"text":"Erros comuns"},{"type":"list","items":["Tentar mudar tudo na mesma semana","Definir metas vagas sem horário ou gatilho","Punir-se por falhas pontuais em vez de retomar","Comparar ritmo com influenciadores ou terceiros"]},{"type":"heading","level":2,"text":"Perguntas frequentes"},{"type":"faq","items":[{"question":"Quanto tempo leva para formar um hábito?","answer":"Varia de 18 a 250 dias conforme complexidade. Consistência importa mais que velocidade."},{"question":"E se eu falhar um dia?","answer":"Retome no dia seguinte. Um dia perdido não apaga progresso — duas semanas abandonadas sim."},{"question":"Preciso de aplicativo?","answer":"Não. Calendário de parede ou checklist no celular funcionam. Apps ajudam quem gosta de métricas."}]},{"type":"heading","level":2,"text":"Conclusão"},{"type":"paragraph","text":"Hábitos saudáveis são construídos em camadas. Escolha um, domine-o e só então adicione o próximo."},{"type":"heading","level":2,"text":"Continue no Clube Saúde & Bem"},{"type":"paragraph","html":"<p>Quer protocolos premium, biblioteca ampliada e acompanhamento contínuo? O <strong>Clube Saúde &amp; Bem</strong> reúne ferramentas avançadas e conteúdo exclusivo para acelerar sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'longevidade', 'Hábitos', 'Dr. Rafael Costa', 'Nutrição Clínica', '9 min', '04 Jun 2026', false, false, '/blog/categories/longevidade.svg', 'Como criar hábitos saudáveis | Guia Saúde & Bem', 'Ciência comportamental aplicada: como instalar hábitos que duram com gatilhos, rotinas mínimas e recompensas realistas.', 'como, criar, habitos, saudaveis, longevidade, saúde, bem-estar, saúde e bem', '/blog/categories/longevidade.svg', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a7100001-0001-4001-8001-000000000005', 'alimentacao-saudavel-iniciantes', 'Alimentação saudável para iniciantes', 'Por onde começar uma alimentação equilibrada: prato inteligente, proteínas, fibras e redução de ultraprocessados sem dietas restritivas.', '[{"type":"image","url":"/blog/categories/emagrecimento.svg","alt":"Capa: Alimentação saudável para iniciantes"},{"type":"heading","level":2,"text":"Introdução"},{"type":"paragraph","text":"Alimentação saudável para iniciantes não significa eliminar tudo que você gosta — significa melhorar a qualidade do que está no prato na maior parte do tempo."},{"type":"paragraph","text":"Foco em vegetais, proteínas magras, gorduras boas e carboidratos integrais cria base sólida sem contagem obsessiva de calorias."},{"type":"heading","level":2,"text":"Benefícios"},{"type":"list","items":["Mais saciedade e energia estável","Melhora de marcadores metabólicos","Digestão mais confortável","Relação mais leve com a comida"]},{"type":"heading","level":2,"text":"Como aplicar"},{"type":"list","items":["Use o método do prato: metade vegetais, um quarto proteína, um quarto carboidrato integral.","Inclua proteína em todas as refeições principais.","Planeje duas refeições da semana com antecedência.","Substitua gradualmente ultraprocessados por versões simples.","Beba água como bebida principal ao longo do dia."],"ordered":true},{"type":"heading","level":2,"text":"Erros comuns"},{"type":"list","items":["Pular refeições e compensar à noite","Eliminar grupos alimentares sem orientação","Confiar em rótulos ''fit'' sem ler ingredientes","Esperar perfeição — 80% de aderência já gera resultado"]},{"type":"heading","level":2,"text":"Perguntas frequentes"},{"type":"faq","items":[{"question":"Preciso contar calorias?","answer":"Não necessariamente no início. Qualidade e porções conscientes já melhoram muito o padrão alimentar."},{"question":"Carboidrato é vilão?","answer":"Não. Carboidratos integrais e em porção adequada são aliados de energia e fibras."},{"question":"Quando consultar nutricionista?","answer":"Se houver condição clínica, histórico de transtorno alimentar ou dúvidas sobre suplementação."}]},{"type":"heading","level":2,"text":"Conclusão"},{"type":"paragraph","text":"Alimentação saudável é habilidade que se aprende. Comece pelo próximo prato, não pela dieta perfeita."},{"type":"heading","level":2,"text":"Continue no Clube Saúde & Bem"},{"type":"paragraph","html":"<p>Quer protocolos premium, biblioteca ampliada e acompanhamento contínuo? O <strong>Clube Saúde &amp; Bem</strong> reúne ferramentas avançadas e conteúdo exclusivo para acelerar sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'emagrecimento', 'Nutrição', 'Dra. Marina Alves', 'Medicina Preventiva', '10 min', '05 Jun 2026', false, false, '/blog/categories/emagrecimento.svg', 'Alimentação saudável para iniciantes | Guia Saúde & Bem', 'Por onde começar uma alimentação equilibrada: prato inteligente, proteínas, fibras e redução de ultraprocessados sem dietas restritivas.', 'alimentacao, saudavel, iniciantes, emagrecimento, saúde, bem-estar, saúde e bem', '/blog/categories/emagrecimento.svg', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a7100001-0001-4001-8001-000000000006', 'saude-intestinal-bem-estar', 'Saúde intestinal e bem-estar', 'Microbiota, fibras, hidratação e sono: como o intestino influencia energia, humor e imunidade — e o que fazer na prática.', '[{"type":"image","url":"/blog/categories/longevidade.svg","alt":"Capa: Saúde intestinal e bem-estar"},{"type":"heading","level":2,"text":"Introdução"},{"type":"paragraph","text":"O intestino é muito mais que digestão — comunica-se com cérebro, sistema imune e metabolismo. Desequilíbrios intestinais podem se manifestar como fadiga, inchaço ou alterações de humor."},{"type":"paragraph","text":"Hábitos alimentares e de estilo de vida sustentam a diversidade da microbiota sem necessidade de protocolos extremos."},{"type":"heading","level":2,"text":"Benefícios"},{"type":"list","items":["Digestão mais confortável e regular","Suporte à barreira imunológica","Possível melhora de humor e foco","Melhor absorção de nutrientes"]},{"type":"heading","level":2,"text":"Como aplicar"},{"type":"list","items":["Consuma 25–30 g de fibras/dia via vegetais, leguminosas e grãos integrais.","Inclua alimentos fermentados com moderação (iogurte, kefir, chucrute).","Mastigue bem e evite refeições em estado de estresse agudo.","Durma adequadamente — o ritmo circadiano afeta o intestino.","Hidrate-se e movimente-se diariamente."],"ordered":true},{"type":"heading","level":2,"text":"Erros comuns"},{"type":"list","items":["Suplementar probióticos sem estratégia individualizada","Dietas restritivas prolongadas sem supervisão","Ignorar sintomas persistentes (dor, sangue, perda de peso)","Excesso de adoçantes artificiais em busca de ''zero''"]},{"type":"heading","level":2,"text":"Perguntas frequentes"},{"type":"faq","items":[{"question":"Probiótico resolve tudo?","answer":"Não. Alimentação com fibras e diversidade vegetal é a base. Probióticos podem complementar casos específicos."},{"question":"Intolerâncias são comuns?","answer":"Sim, mas autodiagnóstico pode eliminar alimentos importantes. Teste com profissional quando possível."},{"question":"Quanto tempo para sentir diferença?","answer":"Mudanças digestivas leves podem aparecer em 2–4 semanas de hábitos consistentes."}]},{"type":"heading","level":2,"text":"Conclusão"},{"type":"paragraph","text":"Saúde intestinal se constrói com variedade alimentar, sono e movimento — pilares simples com impacto profundo."},{"type":"heading","level":2,"text":"Continue no Clube Saúde & Bem"},{"type":"paragraph","html":"<p>Quer protocolos premium, biblioteca ampliada e acompanhamento contínuo? O <strong>Clube Saúde &amp; Bem</strong> reúne ferramentas avançadas e conteúdo exclusivo para acelerar sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'longevidade', 'Saúde intestinal', 'Dr. Rafael Costa', 'Nutrição Clínica', '9 min', '06 Jun 2026', false, false, '/blog/categories/longevidade.svg', 'Saúde intestinal e bem-estar | Guia Saúde & Bem', 'Microbiota, fibras, hidratação e sono: como o intestino influencia energia, humor e imunidade — e o que fazer na prática.', 'saude, intestinal, bem, estar, longevidade, saúde, bem-estar, saúde e bem', '/blog/categories/longevidade.svg', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a7100001-0001-4001-8001-000000000007', 'como-aumentar-energia-naturalmente', 'Como aumentar a energia naturalmente', 'Sono, alimentação, hidratação e movimento: estratégias para energia estável sem depender só de café e estimulantes.', '[{"type":"image","url":"/blog/categories/longevidade.svg","alt":"Capa: Como aumentar a energia naturalmente"},{"type":"heading","level":2,"text":"Introdução"},{"type":"paragraph","text":"Fadiga frequente raramente se resolve apenas com mais cafeína. Energia sustentável vem da interação entre sono reparador, nutrição equilibrada, hidratação e atividade física regular."},{"type":"paragraph","text":"Identificar gatilhos de queda de energia — almoço pesado, desidratação, sedentarismo — permite correções práticas."},{"type":"heading","level":2,"text":"Benefícios"},{"type":"list","items":["Menos picos e quedas ao longo do dia","Melhor desempenho cognitivo","Redução de dependência de estimulantes","Humor e motivação mais estáveis"]},{"type":"heading","level":2,"text":"Como aplicar"},{"type":"list","items":["Priorize 7–8 horas de sono com horário regular.","Exponha-se à luz natural pela manhã por 10–15 minutos.","Faça café da manhã com proteína e fibras.","Caminhe 10 minutos após refeições principais.","Beba água ao acordar e entre refeições."],"ordered":true},{"type":"heading","level":2,"text":"Erros comuns"},{"type":"list","items":["Substituir refeições por apenas café","Pular o café da manhã sem estratégia nutricional","Trabalhar sentado por horas sem pausas","Ignorar anemia ou tireoide em fadiga persistente"]},{"type":"heading","level":2,"text":"Perguntas frequentes"},{"type":"faq","items":[{"question":"Café é prejudicial?","answer":"Moderado e até o meio da manhã pode ajudar. Excesso ou uso tardio prejudica sono e energia do dia seguinte."},{"question":"Vitaminas energéticas funcionam?","answer":"Só corrigem deficiência comprovada. Exames orientam suplementação segura."},{"question":"Cochilo ajuda na energia?","answer":"Cochilos curtos (power nap) de 15–20 minutos podem restaurar alerta sem prejudicar a noite."}]},{"type":"heading","level":2,"text":"Conclusão"},{"type":"paragraph","text":"Energia natural é resultado de rotina integrada. Ajuste sono e alimentação antes de buscar atalhos."},{"type":"heading","level":2,"text":"Continue no Clube Saúde & Bem"},{"type":"paragraph","html":"<p>Quer protocolos premium, biblioteca ampliada e acompanhamento contínuo? O <strong>Clube Saúde &amp; Bem</strong> reúne ferramentas avançadas e conteúdo exclusivo para acelerar sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'longevidade', 'Energia', 'Dra. Marina Alves', 'Medicina Preventiva', '8 min', '07 Jun 2026', false, false, '/blog/categories/longevidade.svg', 'Como aumentar a energia naturalmente | Guia Saúde & Bem', 'Sono, alimentação, hidratação e movimento: estratégias para energia estável sem depender só de café e estimulantes.', 'como, aumentar, energia, naturalmente, longevidade, saúde, bem-estar, saúde e bem', '/blog/categories/longevidade.svg', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a7100001-0001-4001-8001-000000000008', 'hidratacao-inteligente', 'Hidratação inteligente', 'Como beber água de forma estratégica ao longo do dia — metas, sinais corporais e ajustes para treino e calor.', '[{"type":"image","url":"/blog/categories/hidratacao.svg","alt":"Capa: Hidratação inteligente"},{"type":"heading","level":2,"text":"Introdução"},{"type":"paragraph","text":"Hidratação inteligente vai além de ''beber quando sentir sede''. Distribuir água ao longo do dia mantém funções cognitivas, digestivas e cardiovasculares estáveis."},{"type":"paragraph","text":"Clima, atividade física e alimentação influenciam a necessidade diária — personalize com sinais simples do corpo."},{"type":"heading","level":2,"text":"Benefícios"},{"type":"list","items":["Melhor foco e clareza mental","Pele e digestão mais equilibradas","Desempenho físico otimizado","Menos dores de cabeça relacionadas à desidratação"]},{"type":"heading","level":2,"text":"Como aplicar"},{"type":"list","items":["Beba um copo de água ao acordar.","Use meta base de ~35 ml/kg, ajustando para calor e treino.","Leve garrafa visível na mesa de trabalho.","Inclua frutas e sopas na conta hídrica diária.","Observe cor da urina: amarelo claro é referência útil."],"ordered":true},{"type":"heading","level":2,"text":"Erros comuns"},{"type":"list","items":["Beber grande volume de uma vez só","Substituir água por refrigerantes ou sucos açucarados","Esperar sede intensa como único sinal","Ignorar reposição após suor intenso"]},{"type":"heading","level":2,"text":"Perguntas frequentes"},{"type":"faq","items":[{"question":"Água com gás conta?","answer":"Sim, hidrata. Em refluxo ou gases, prefira água sem gás."},{"question":"Quanto beber no treino?","answer":"150–250 ml a cada 15–20 minutos em atividade moderada; mais em calor extremo."},{"question":"Pode beber água durante as refeições?","answer":"Sim, com moderação. Não prejudica digestão na maioria das pessoas."}]},{"type":"heading","level":2,"text":"Conclusão"},{"type":"paragraph","text":"Hidratação inteligente é hábito distribuído, não maratona de litros. Pequenos goles frequentes vencem."},{"type":"heading","level":2,"text":"Continue no Clube Saúde & Bem"},{"type":"paragraph","html":"<p>Quer protocolos premium, biblioteca ampliada e acompanhamento contínuo? O <strong>Clube Saúde &amp; Bem</strong> reúne ferramentas avançadas e conteúdo exclusivo para acelerar sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'hidratacao', 'Hidratação', 'Dr. Rafael Costa', 'Nutrição Clínica', '7 min', '08 Jun 2026', false, false, '/blog/categories/hidratacao.svg', 'Hidratação inteligente | Guia Saúde & Bem', 'Como beber água de forma estratégica ao longo do dia — metas, sinais corporais e ajustes para treino e calor.', 'hidratacao, inteligente, hidratacao, saúde, bem-estar, saúde e bem', '/blog/categories/hidratacao.svg', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a7100001-0001-4001-8001-000000000009', 'magnesio-qualidade-sono', 'Magnésio e qualidade do sono', 'O que a ciência diz sobre magnésio, relaxamento muscular e sono — alimentos, suplementação e cautelas.', '[{"type":"image","url":"/blog/categories/sono.svg","alt":"Capa: Magnésio e qualidade do sono"},{"type":"heading","level":2,"text":"Introdução"},{"type":"paragraph","text":"O magnésio participa de centenas de reações no corpo, incluindo relaxamento muscular e regulação do sistema nervoso. Deficiência subclínica é comum e pode afetar qualidade do sono."},{"type":"paragraph","text":"Antes de suplementar, vale otimizar fontes alimentares e hábitos de higiene do sono."},{"type":"heading","level":2,"text":"Benefícios"},{"type":"list","items":["Suporte ao relaxamento muscular noturno","Possível redução de despertares noturnos","Participação na regulação do ritmo circadiano","Complemento a rotina de descanso — não substituto"]},{"type":"heading","level":2,"text":"Como aplicar"},{"type":"list","items":["Inclua castanhas, sementes, folhas verdes e leguminosas.","Mantenha rotina de sono consistente em paralelo.","Se suplementar, prefira formas bem toleradas e dose orientada.","Evite dose alta sem avaliação — pode causar desconforto intestinal.","Revise medicamentos que interagem com magnésio com seu médico."],"ordered":true},{"type":"heading","level":2,"text":"Erros comuns"},{"type":"list","items":["Esperar que suplemento compense má higiene do sono","Megadoses sem orientação profissional","Ignorar diarreia ou cólicas como sinal de excesso","Substituir investigação de apneia ou insônia clínica"]},{"type":"heading","level":2,"text":"Perguntas frequentes"},{"type":"faq","items":[{"question":"Qual melhor horário para tomar magnésio?","answer":"Muitas pessoas preferem 1–2 horas antes de dormir, mas o mais importante é consistência e tolerância digestiva."},{"question":"Magnésio é seguro para todos?","answer":"Pessoas com doença renal ou em uso de certos medicamentos precisam de avaliação médica."},{"question":"Comida basta?","answer":"Frequentemente sim. Suplemento entra quando dieta e exames indicam necessidade."}]},{"type":"heading","level":2,"text":"Conclusão"},{"type":"paragraph","text":"Magnésio pode apoiar o sono como peça do quebra-cabeça — rotina, ambiente e alimentação continuam centrais."},{"type":"heading","level":2,"text":"Continue no Clube Saúde & Bem"},{"type":"paragraph","html":"<p>Quer protocolos premium, biblioteca ampliada e acompanhamento contínuo? O <strong>Clube Saúde &amp; Bem</strong> reúne ferramentas avançadas e conteúdo exclusivo para acelerar sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'sono', 'Sono', 'Dra. Marina Alves', 'Medicina Preventiva', '8 min', '09 Jun 2026', false, false, '/blog/categories/sono.svg', 'Magnésio e qualidade do sono | Guia Saúde & Bem', 'O que a ciência diz sobre magnésio, relaxamento muscular e sono — alimentos, suplementação e cautelas.', 'magnesio, qualidade, sono, sono, saúde, bem-estar, saúde e bem', '/blog/categories/sono.svg', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a7100001-0001-4001-8001-000000000010', 'como-melhorar-produtividade', 'Como melhorar a produtividade', 'Produtividade sustentável une sono, foco, pausas estratégicas e organização — sem glorificar exaustão.', '[{"type":"image","url":"/blog/categories/longevidade.svg","alt":"Capa: Como melhorar a produtividade"},{"type":"heading","level":2,"text":"Introdução"},{"type":"paragraph","text":"Produtividade real não é fazer mais a qualquer custo — é entregar o que importa com energia preservada. Sono ruim, alimentação desequilibrada e multitarefa constante sabotam resultados."},{"type":"paragraph","text":"Estruturar o dia em blocos de foco e recuperação aumenta qualidade do trabalho e bem-estar."},{"type":"heading","level":2,"text":"Benefícios"},{"type":"list","items":["Mais entregas relevantes com menos retrabalho","Menor sensação de sobrecarga","Melhor equilíbrio entre trabalho e descanso","Clareza de prioridades"]},{"type":"heading","level":2,"text":"Como aplicar"},{"type":"list","items":["Defina três prioridades máximas por dia.","Use blocos de 45–90 minutos de foco sem notificações.","Faça pausas de 5 minutos a cada hora — movimento e água.","Proteja o primeiro bloco da manhã para tarefa mais importante.","Encerre o dia com revisão de 5 minutos para o dia seguinte."],"ordered":true},{"type":"heading","level":2,"text":"Erros comuns"},{"type":"list","items":["Confundir ocupação com produtividade","Trabalhar até exaustão como badge de honra","Não delegar ou dizer não","Ignorar sono em nome de ''mais horas''"]},{"type":"heading","level":2,"text":"Perguntas frequentes"},{"type":"faq","items":[{"question":"Técnica Pomodoro funciona?","answer":"Sim para muitas pessoas. Ajuste intervalos ao seu tipo de tarefa e energia."},{"question":"Multitarefa é eficiente?","answer":"Estudos mostram queda de qualidade. Monotarefa com blocos é superior na maioria dos casos."},{"question":"Produtividade e saúde mental?","answer":"Estão ligadas. Pausas e limites protegem desempenho a longo prazo."}]},{"type":"heading","level":2,"text":"Conclusão"},{"type":"paragraph","text":"Produtividade sustentável protege sua saúde enquanto entrega resultados. Menos urgência artificial, mais intenção."},{"type":"heading","level":2,"text":"Continue no Clube Saúde & Bem"},{"type":"paragraph","html":"<p>Quer protocolos premium, biblioteca ampliada e acompanhamento contínuo? O <strong>Clube Saúde &amp; Bem</strong> reúne ferramentas avançadas e conteúdo exclusivo para acelerar sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'longevidade', 'Produtividade', 'Dr. Rafael Costa', 'Nutrição Clínica', '8 min', '10 Jun 2026', false, false, '/blog/categories/longevidade.svg', 'Como melhorar a produtividade | Guia Saúde & Bem', 'Produtividade sustentável une sono, foco, pausas estratégicas e organização — sem glorificar exaustão.', 'como, melhorar, produtividade, longevidade, saúde, bem-estar, saúde e bem', '/blog/categories/longevidade.svg', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a7100001-0001-4001-8001-000000000011', 'alongamento-diario', 'Alongamento diário', 'Rotina de alongamento de 10 minutos para mobilidade, postura e alívio de tensão — segura para iniciantes.', '[{"type":"image","url":"/blog/categories/emagrecimento.svg","alt":"Capa: Alongamento diário"},{"type":"heading","level":2,"text":"Introdução"},{"type":"paragraph","text":"Alongamento diário melhora amplitude de movimento, alivia tensão de horas sentado e prepara o corpo para atividade. Não exige academia — apenas consistência."},{"type":"paragraph","text":"Movimentos lentos e respiração consciente aumentam segurança e benefício."},{"type":"heading","level":2,"text":"Benefícios"},{"type":"list","items":["Melhora de postura e conforto nas atividades diárias","Redução de rigidez muscular","Preparação para caminhada ou treino","Momento de pausa mental"]},{"type":"heading","level":2,"text":"Como aplicar"},{"type":"list","items":["Reserve 10 minutos após acordar ou antes de dormir.","Aqueça com movimento leve por 2 minutos.","Segure cada alongamento 20–30 segundos sem dor.","Inclua pescoço, ombros, quadril e posteriores de coxa.","Respire profundamente — não prenda a respiração."],"ordered":true},{"type":"heading","level":2,"text":"Erros comuns"},{"type":"list","items":["Alongar até sentir dor aguda","Movimentos bruscos ou balísticos sem preparo","Pular dias consecutivos na primeira semana","Substituir avaliação fisioterapêutica em dor crônica"]},{"type":"heading","level":2,"text":"Perguntas frequentes"},{"type":"faq","items":[{"question":"Alongar antes ou depois do treino?","answer":"Mobilidade leve antes; alongamento mais longo após atividade ou em momento separado."},{"question":"Quantos dias por semana?","answer":"Diariamente em versão curta já traz benefícios para a maioria."},{"question":"Ajuda na dor nas costas?","answer":"Pode aliviar tensão postural leve. Dor persistente exige avaliação profissional."}]},{"type":"heading","level":2,"text":"Conclusão"},{"type":"paragraph","text":"Dez minutos diários de alongamento são um dos investimentos mais acessíveis em mobilidade e conforto corporal."},{"type":"heading","level":2,"text":"Continue no Clube Saúde & Bem"},{"type":"paragraph","html":"<p>Quer protocolos premium, biblioteca ampliada e acompanhamento contínuo? O <strong>Clube Saúde &amp; Bem</strong> reúne ferramentas avançadas e conteúdo exclusivo para acelerar sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'emagrecimento', 'Movimento', 'Dra. Marina Alves', 'Medicina Preventiva', '7 min', '11 Jun 2026', false, false, '/blog/categories/emagrecimento.svg', 'Alongamento diário | Guia Saúde & Bem', 'Rotina de alongamento de 10 minutos para mobilidade, postura e alívio de tensão — segura para iniciantes.', 'alongamento, diario, emagrecimento, saúde, bem-estar, saúde e bem', '/blog/categories/emagrecimento.svg', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a7100001-0001-4001-8001-000000000012', 'saude-mental-rotina', 'Saúde mental e rotina', 'Como estruturar o dia para proteger saúde mental: sono, limites digitais, conexão social e autocuidado prático.', '[{"type":"image","url":"/blog/categories/longevidade.svg","alt":"Capa: Saúde mental e rotina"},{"type":"heading","level":2,"text":"Introdução"},{"type":"paragraph","text":"Saúde mental floresce quando rotina oferece previsibilidade, descanso e conexão. Caos constante e sono irregular aumentam vulnerabilidade a ansiedade e esgotamento."},{"type":"paragraph","text":"Pequenos rituais diários funcionam como âncoras emocionais."},{"type":"heading","level":2,"text":"Benefícios"},{"type":"list","items":["Maior sensação de estabilidade","Melhor regulação emocional","Sono e energia mais consistentes","Relações mais presentes"]},{"type":"heading","level":2,"text":"Como aplicar"},{"type":"list","items":["Mantenha horário de sono e despertar estável.","Inclua contato social real semanal — presencial ou chamada.","Limite notícias e redes em blocos definidos.","Pratique gratidão ou journaling 3 minutos/dia.","Movimente-se — exercício é antidepressivo moderado com evidência."],"ordered":true},{"type":"heading","level":2,"text":"Erros comuns"},{"type":"list","items":["Isolamento prolongado","Automedicação com álcool ou substâncias","Ignorar sintomas persistentes por vergonha","Rotina 100% produtividade sem lazer"]},{"type":"heading","level":2,"text":"Perguntas frequentes"},{"type":"faq","items":[{"question":"Rotina engessa?","answer":"Boa rotina tem flexibilidade planejada. Estrutura reduz ansiedade, não elimina espontaneidade."},{"question":"Terapia é necessária?","answer":"Não para todos, mas é recurso valioso preventivo e terapêutico. Não há requisito de crise."},{"question":"Apps de meditação ajudam?","answer":"Podem facilitar início. O importante é prática regular, com ou sem app."}]},{"type":"heading","level":2,"text":"Conclusão"},{"type":"paragraph","text":"Cuidar da saúde mental na rotina é ato de manutenção — como escovar os dentes, feito diariamente."},{"type":"heading","level":2,"text":"Continue no Clube Saúde & Bem"},{"type":"paragraph","html":"<p>Quer protocolos premium, biblioteca ampliada e acompanhamento contínuo? O <strong>Clube Saúde &amp; Bem</strong> reúne ferramentas avançadas e conteúdo exclusivo para acelerar sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'longevidade', 'Saúde mental', 'Dr. Rafael Costa', 'Nutrição Clínica', '9 min', '12 Jun 2026', false, false, '/blog/categories/longevidade.svg', 'Saúde mental e rotina | Guia Saúde & Bem', 'Como estruturar o dia para proteger saúde mental: sono, limites digitais, conexão social e autocuidado prático.', 'saude, mental, rotina, longevidade, saúde, bem-estar, saúde e bem', '/blog/categories/longevidade.svg', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a7100001-0001-4001-8001-000000000013', 'tecnicas-respiracao', 'Técnicas de respiração', 'Respiração diafragmática, box breathing e pausas conscientes para reduzir estresse e melhorar foco em minutos.', '[{"type":"image","url":"/blog/categories/longevidade.svg","alt":"Capa: Técnicas de respiração"},{"type":"heading","level":2,"text":"Introdução"},{"type":"paragraph","text":"A respiração é a ponte mais rápida entre mente e corpo. Padrões lentos e profundos ativam resposta de relaxamento e reduzem frequência cardíaca em minutos."},{"type":"paragraph","text":"Técnicas simples podem ser usadas antes de reuniões, ao acordar ou ao deitar."},{"type":"heading","level":2,"text":"Benefícios"},{"type":"list","items":["Redução imediata de tensão percebida","Melhora de foco e clareza","Suporte ao sono quando praticada à noite","Ferramenta gratuita e sempre disponível"]},{"type":"heading","level":2,"text":"Como aplicar"},{"type":"list","items":["Diafragmática: inspire 4s pelo nariz, expanda abdômen; expire 6s pela boca.","Box breathing: 4s inspirar, 4s segurar, 4s expirar, 4s pausa — repita 4 ciclos.","Pratique 5 minutos ao acordar ou em pausa do trabalho.","Use antes de dormir para desacelerar.","Combine com postura ereta e ombros relaxados."],"ordered":true},{"type":"heading","level":2,"text":"Erros comuns"},{"type":"list","items":["Hiperventilar em busca de efeito rápido","Praticar apenas em crises — consistência importa","Forçar retenção se sentir tontura","Substituir tratamento em transtornos de ansiedade grave"]},{"type":"heading","level":2,"text":"Perguntas frequentes"},{"type":"faq","items":[{"question":"Quanto tempo até sentir efeito?","answer":"Muitas pessoas notam calma em 2–5 minutos de prática focada."},{"question":"Crianças podem praticar?","answer":"Sim, versões simplificadas e lúdicas funcionam bem."},{"question":"Respiração substitui medicação?","answer":"Não. É complemento. Decisões sobre medicação são com médico."}]},{"type":"heading","level":2,"text":"Conclusão"},{"type":"paragraph","text":"Técnicas de respiração são kit de emergência e manutenção diária para equilíbrio nervoso."},{"type":"heading","level":2,"text":"Continue no Clube Saúde & Bem"},{"type":"paragraph","html":"<p>Quer protocolos premium, biblioteca ampliada e acompanhamento contínuo? O <strong>Clube Saúde &amp; Bem</strong> reúne ferramentas avançadas e conteúdo exclusivo para acelerar sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'longevidade', 'Respiração', 'Dra. Marina Alves', 'Medicina Preventiva', '7 min', '13 Jun 2026', false, false, '/blog/categories/longevidade.svg', 'Técnicas de respiração | Guia Saúde & Bem', 'Respiração diafragmática, box breathing e pausas conscientes para reduzir estresse e melhorar foco em minutos.', 'tecnicas, respiracao, longevidade, saúde, bem-estar, saúde e bem', '/blog/categories/longevidade.svg', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a7100001-0001-4001-8001-000000000014', 'como-melhorar-imunidade', 'Como melhorar a imunidade', 'Sono, nutrição, exercício e gestão de estresse: pilares com evidência para sistema imune resiliente — sem ''imunidade mágica''.', '[{"type":"image","url":"/blog/categories/longevidade.svg","alt":"Capa: Como melhorar a imunidade"},{"type":"heading","level":2,"text":"Introdução"},{"type":"paragraph","text":"Imunidade forte não vem de um único superalimento — vem de hábitos integrados que reduzem inflamação crônica e suportam células de defesa."},{"type":"paragraph","text":"Sono, micronutrientes via alimentação variada e movimento moderado são os pilares com melhor evidência."},{"type":"heading","level":2,"text":"Benefícios"},{"type":"list","items":["Menor susceptibilidade a infecções respiratórias frequentes","Recuperação mais rápida quando adoece","Saúde metabólica e inflamatória equilibrada","Melhor resposta a vacinas — associada a estilo de vida"]},{"type":"heading","level":2,"text":"Como aplicar"},{"type":"list","items":["Durma 7–9 horas com regularidade.","Coma arco-íris de vegetais e frutas diariamente.","Pratique exercício moderado 150 min/semana.","Higienize mãos e mantenha vacinação em dia.","Gerencie estresse crônico com pausas e movimento."],"ordered":true},{"type":"heading","level":2,"text":"Erros comuns"},{"type":"list","items":["Megadoses de vitamina C ou zinco sem necessidade","Excesso de exercício intenso sem recuperação","Privação de sono em nome de produtividade","Acreditar em ''detox'' ou produtos milagrosos"]},{"type":"heading","level":2,"text":"Perguntas frequentes"},{"type":"faq","items":[{"question":"Suplementos imunidade funcionam?","answer":"Corrigem deficiências específicas. Para pessoa saudável, alimentação costuma bastar."},{"question":"Exercício intenso imunidade?","answer":"Moderado fortalece; excesso sem descanso pode temporariamente suprimir defesas."},{"question":"Idosos precisam de cuidados extras?","answer":"Sim — sono, proteína adequada e vacinação são ainda mais relevantes."}]},{"type":"heading","level":2,"text":"Conclusão"},{"type":"paragraph","text":"Imunidade resiliente é estilo de vida, não pílula. Consistência nos pilares básicos é a melhor estratégia."},{"type":"heading","level":2,"text":"Continue no Clube Saúde & Bem"},{"type":"paragraph","html":"<p>Quer protocolos premium, biblioteca ampliada e acompanhamento contínuo? O <strong>Clube Saúde &amp; Bem</strong> reúne ferramentas avançadas e conteúdo exclusivo para acelerar sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'longevidade', 'Imunidade', 'Dr. Rafael Costa', 'Nutrição Clínica', '9 min', '14 Jun 2026', false, false, '/blog/categories/longevidade.svg', 'Como melhorar a imunidade | Guia Saúde & Bem', 'Sono, nutrição, exercício e gestão de estresse: pilares com evidência para sistema imune resiliente — sem ''imunidade mágica''.', 'como, melhorar, imunidade, longevidade, saúde, bem-estar, saúde e bem', '/blog/categories/longevidade.svg', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a7100001-0001-4001-8001-000000000015', 'habitos-matinais-saudaveis', 'Hábitos matinais saudáveis', 'Rotina matinal enxuta: luz natural, hidratação, movimento e café da manhã inteligente para começar o dia com energia.', '[{"type":"image","url":"/blog/categories/longevidade.svg","alt":"Capa: Hábitos matinais saudáveis"},{"type":"heading","level":2,"text":"Introdução"},{"type":"paragraph","text":"A manhã define o tom do dia. Hábitos matinais saudáveis não precisam durar duas horas — uma sequência de 20 a 30 minutos já alinha ritmo circadiano e energia."},{"type":"paragraph","text":"Previsibilidade reduz fadiga de decisão e facilita consistência."},{"type":"heading","level":2,"text":"Benefícios"},{"type":"list","items":["Melhor humor e alerta nas primeiras horas","Metabolismo e apetite mais regulados","Sensação de controle sobre o dia","Base para noite de sono mais regular"]},{"type":"heading","level":2,"text":"Como aplicar"},{"type":"list","items":["Acorde no mesmo horário ±30 minutos.","Beba água ao levantar.","Exponha-se à luz natural por 10 minutos.","Movimento leve: caminhada, alongamento ou 20 agachamentos.","Café da manhã com proteína e fibras."],"ordered":true},{"type":"heading","level":2,"text":"Erros comuns"},{"type":"list","items":["Checar celular ainda na cama por 30+ minutos","Pular café da manhã e compensar com ultraprocessados","Rotina matinal longa demais para manter","Cafeína imediata sem hidratação"]},{"type":"heading","level":2,"text":"Perguntas frequentes"},{"type":"faq","items":[{"question":"Preciso acordar cedo?","answer":"Consistência importa mais que horário absoluto. Alinhe à sua realidade de trabalho."},{"question":"Jejum matinal é obrigatório?","answer":"Não. Alguns preferem; outros precisam comer cedo. Escolha o que sustenta energia."},{"question":"E se tenho filhos pequenos?","answer":"Versão mínima: água, luz e 5 minutos de movimento já ajudam."}]},{"type":"heading","level":2,"text":"Conclusão"},{"type":"paragraph","text":"Manhãs saudáveis são construídas em versão mínima viável — expanda só depois de consolidar o básico."},{"type":"heading","level":2,"text":"Continue no Clube Saúde & Bem"},{"type":"paragraph","html":"<p>Quer protocolos premium, biblioteca ampliada e acompanhamento contínuo? O <strong>Clube Saúde &amp; Bem</strong> reúne ferramentas avançadas e conteúdo exclusivo para acelerar sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'longevidade', 'Rotina', 'Dra. Marina Alves', 'Medicina Preventiva', '8 min', '15 Jun 2026', false, false, '/blog/categories/longevidade.svg', 'Hábitos matinais saudáveis | Guia Saúde & Bem', 'Rotina matinal enxuta: luz natural, hidratação, movimento e café da manhã inteligente para começar o dia com energia.', 'habitos, matinais, saudaveis, longevidade, saúde, bem-estar, saúde e bem', '/blog/categories/longevidade.svg', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a7100001-0001-4001-8001-000000000016', 'controle-ansiedade', 'Controle da ansiedade', 'Ferramentas práticas para ansiedade leve a moderada: respiração, rotina, movimento e quando buscar ajuda profissional.', '[{"type":"image","url":"/blog/categories/longevidade.svg","alt":"Capa: Controle da ansiedade"},{"type":"heading","level":2,"text":"Introdução"},{"type":"paragraph","text":"Ansiedade é resposta natural a incerteza — torna-se problema quando frequente, intensa e interfere na vida. Hábitos de estilo de vida e técnicas comportamentais ajudam muitas pessoas."},{"type":"paragraph","text":"Este conteúdo é educativo e não substitui avaliação psicológica ou psiquiátrica quando necessária."},{"type":"heading","level":2,"text":"Benefícios"},{"type":"list","items":["Redução de sintomas físicos (tensão, palpitação leve)","Maior sensação de controle","Sono menos fragmentado","Melhor tolerância a situações desafiadoras"]},{"type":"heading","level":2,"text":"Como aplicar"},{"type":"list","items":["Pratique respiração lenta 5 minutos ao sentir aceleração.","Limite cafeína e álcool — ambos amplificam ansiedade.","Mantenha rotina de sono e exercício regular.","Nomeie preocupações por escrito e defina uma ação concreta.","Reduza consumo de notícias alarmistas."],"ordered":true},{"type":"heading","level":2,"text":"Erros comuns"},{"type":"list","items":["Evitar todas as situações que geram desconforto","Automedicação com álcool ou sedativos sem prescrição","Isolamento social prolongado","Esperar que ansiedade grave suma só com força de vontade"]},{"type":"heading","level":2,"text":"Perguntas frequentes"},{"type":"faq","items":[{"question":"Ansiedade e ataque de pânico são iguais?","answer":"Pânico é episódio intenso e limitado. Ansiedade pode ser mais contínua. Ambos merecem atenção."},{"question":"Terapia cognitivo-comportamental ajuda?","answer":"Sim, é uma das abordagens com melhor evidência para transtornos de ansiedade."},{"question":"Quando ir ao médico?","answer":"Se sintomas persistem semanas, atrapalham trabalho/sono ou há pensamentos de autolesão."}]},{"type":"heading","level":2,"text":"Conclusão"},{"type":"paragraph","text":"Controle da ansiedade combina ferramentas diárias e suporte profissional quando necessário — pedir ajuda é força, não fraqueza."},{"type":"heading","level":2,"text":"Continue no Clube Saúde & Bem"},{"type":"paragraph","html":"<p>Quer protocolos premium, biblioteca ampliada e acompanhamento contínuo? O <strong>Clube Saúde &amp; Bem</strong> reúne ferramentas avançadas e conteúdo exclusivo para acelerar sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'longevidade', 'Ansiedade', 'Dr. Rafael Costa', 'Nutrição Clínica', '9 min', '16 Jun 2026', false, false, '/blog/categories/longevidade.svg', 'Controle da ansiedade | Guia Saúde & Bem', 'Ferramentas práticas para ansiedade leve a moderada: respiração, rotina, movimento e quando buscar ajuda profissional.', 'controle, ansiedade, longevidade, saúde, bem-estar, saúde e bem', '/blog/categories/longevidade.svg', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a7100001-0001-4001-8001-000000000017', 'como-criar-rotina-sustentavel', 'Como criar uma rotina sustentável', 'Monte uma rotina de saúde que cabe na vida real — blocos flexíveis, prioridades claras e revisão semanal.', '[{"type":"image","url":"/blog/categories/longevidade.svg","alt":"Capa: Como criar uma rotina sustentável"},{"type":"heading","level":2,"text":"Introdução"},{"type":"paragraph","text":"Rotina sustentável é aquela que você mantém por meses, não por três dias de motivação. Ela respeita trabalho, família e imprevistos sem desmoronar."},{"type":"paragraph","text":"Flexibilidade planejada é tão importante quanto disciplina."},{"type":"heading","level":2,"text":"Benefícios"},{"type":"list","items":["Consistência sem burnout","Progresso mensurável em saúde","Menos culpa por dias imperfeitos","Integração natural de sono, movimento e alimentação"]},{"type":"heading","level":2,"text":"Como aplicar"},{"type":"list","items":["Liste não negociáveis: sono, uma refeição equilibrada, 20 min movimento.","Use blocos de tempo em vez de listas infinitas.","Planeje domingo 15 minutos da semana seguinte.","Tenha plano B para dias caóticos (caminhada 10 min, marmita simples).","Revise sexta: o que funcionou? Ajuste um item só."],"ordered":true},{"type":"heading","level":2,"text":"Erros comuns"},{"type":"list","items":["Copiar rotina de influenciador sem adaptar","Zero margem para imprevistos","Medir sucesso só por peso na balança","Abandonar tudo após um dia ruim"]},{"type":"heading","level":2,"text":"Perguntas frequentes"},{"type":"faq","items":[{"question":"Rotina é para pessoas sem flexibilidade?","answer":"Pelo contrário — rotina bem desenhada cria espaço mental para o imprevisível."},{"question":"Quantos hábitos simultâneos?","answer":"Um a três focos por mês costuma ser sustentável."},{"question":"Fins de semana contam?","answer":"Sim, mas podem ter versão mais leve do mesmo esqueleto horário."}]},{"type":"heading","level":2,"text":"Conclusão"},{"type":"paragraph","text":"Rotina sustentável é contrato consigo mesmo — realista, revisável e gentil."},{"type":"heading","level":2,"text":"Continue no Clube Saúde & Bem"},{"type":"paragraph","html":"<p>Quer protocolos premium, biblioteca ampliada e acompanhamento contínuo? O <strong>Clube Saúde &amp; Bem</strong> reúne ferramentas avançadas e conteúdo exclusivo para acelerar sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'longevidade', 'Rotina', 'Dra. Marina Alves', 'Medicina Preventiva', '8 min', '17 Jun 2026', false, false, '/blog/categories/longevidade.svg', 'Como criar uma rotina sustentável | Guia Saúde & Bem', 'Monte uma rotina de saúde que cabe na vida real — blocos flexíveis, prioridades claras e revisão semanal.', 'como, criar, rotina, sustentavel, longevidade, saúde, bem-estar, saúde e bem', '/blog/categories/longevidade.svg', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a7100001-0001-4001-8001-000000000018', 'exercicios-para-iniciantes', 'Exercícios para iniciantes', 'Por onde começar treinar com segurança: caminhada, força básica e progressão gradual sem academia obrigatória.', '[{"type":"image","url":"/blog/categories/emagrecimento.svg","alt":"Capa: Exercícios para iniciantes"},{"type":"heading","level":2,"text":"Introdução"},{"type":"paragraph","text":"Começar a se exercitar pode intimidar, mas iniciantes se beneficiam enormemente de movimentos simples e progressão lenta. O melhor exercício é o que você repete."},{"type":"paragraph","text":"Combinação de aeróbico leve e força com peso corporal constrói base sólida."},{"type":"heading","level":2,"text":"Benefícios"},{"type":"list","items":["Melhora cardiovascular e muscular","Mais energia e disposição","Suporte à saúde óssea e metabólica","Autoestima e hábito de autocuidado"]},{"type":"heading","level":2,"text":"Como aplicar"},{"type":"list","items":["Semana 1–2: caminhada 20 min, 4x/semana.","Adicione 2x/semana circuito: agachamento, flexão na parede, prancha 20s.","Aumente 10% volume a cada duas semanas.","Aqueça 5 min e alongue ao final.","Hidrate e durma bem para recuperar."],"ordered":true},{"type":"heading","level":2,"text":"Erros comuns"},{"type":"list","items":["Começar com HIIT intenso sem base","Treinar todos os dias sem descanso inicial","Ignorar dor articular aguda","Comparar-se com praticantes avançados"]},{"type":"heading","level":2,"text":"Perguntas frequentes"},{"type":"faq","items":[{"question":"Preciso de academia?","answer":"Não. Peso corporal e caminhada são excelentes pontos de partida."},{"question":"Quanto tempo ver resultados?","answer":"Energia em 2–3 semanas; mudanças corporais visíveis em 6–8 semanas com consistência."},{"question":"Dor muscular normal?","answer":"Leve delayed onset muscle soreness é comum. Dor aguda ou articular não é — pare e avalie."}]},{"type":"heading","level":2,"text":"Conclusão"},{"type":"paragraph","text":"Exercício para iniciantes é sobre começar e continuar — intensidade vem depois."},{"type":"heading","level":2,"text":"Continue no Clube Saúde & Bem"},{"type":"paragraph","html":"<p>Quer protocolos premium, biblioteca ampliada e acompanhamento contínuo? O <strong>Clube Saúde &amp; Bem</strong> reúne ferramentas avançadas e conteúdo exclusivo para acelerar sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'emagrecimento', 'Exercícios', 'Dr. Rafael Costa', 'Nutrição Clínica', '9 min', '18 Jun 2026', false, false, '/blog/categories/emagrecimento.svg', 'Exercícios para iniciantes | Guia Saúde & Bem', 'Por onde começar treinar com segurança: caminhada, força básica e progressão gradual sem academia obrigatória.', 'exercicios, para, iniciantes, emagrecimento, saúde, bem-estar, saúde e bem', '/blog/categories/emagrecimento.svg', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a7100001-0001-4001-8001-000000000019', 'dormir-melhor-sem-medicamentos', 'Como dormir melhor sem medicamentos', 'Higiene do sono, luz, temperatura e rotina comportamental — estratégias não farmacológicas com evidência.', '[{"type":"image","url":"/blog/categories/sono.svg","alt":"Capa: Como dormir melhor sem medicamentos"},{"type":"heading","level":2,"text":"Introdução"},{"type":"paragraph","text":"Muitas pessoas preferem otimizar sono sem medicamentos como primeira linha — e a medicina do sono recomenda higiene e terapia cognitivo-comportamental antes de fármacos em diversos casos."},{"type":"paragraph","text":"Mudanças ambientais e comportamentais podem surpreender pela eficácia quando aplicadas com consistência."},{"type":"heading","level":2,"text":"Benefícios"},{"type":"list","items":["Sono mais natural sem dependência sedativa","Menos efeitos colaterais diurnos","Habilidades duradouras para manutenção","Complemento seguro a tratamentos prescritos"]},{"type":"heading","level":2,"text":"Como aplicar"},{"type":"list","items":["Terapia de restrição de estímulo: cama só para sono e intimidade.","Horário fixo de despertar, mesmo após noite ruim.","Exposição à luz de manhã; escuridão à noite.","Evitar cochilos longos após 15h.","Se não dormir em 20 min, levante e faça atividade calma até sonolência."],"ordered":true},{"type":"heading","level":2,"text":"Erros comuns"},{"type":"list","items":["Ficar na cama acordado por horas frustrado","Usar álcool como indutor de sono","Relógio visível aumentando ansiedade de performance","Abandonar hábitos após uma semana sem resultado"]},{"type":"heading","level":2,"text":"Perguntas frequentes"},{"type":"faq","items":[{"question":"Insônia crônica: higiene basta?","answer":"Pode ajudar muito, mas TCC para insônia (CBT-I) é padrão-ouro. Médico pode indicar."},{"question":"Melatonina é medicamento?","answer":"É hormônio suplementado. Uso pontual pode ajudar jet lag; crônico merece orientação."},{"question":"Quando medicamento é indicado?","answer":"Casos específicos com médico — não é derrota, é ferramenta quando necessária."}]},{"type":"heading","level":2,"text":"Conclusão"},{"type":"paragraph","text":"Dormir melhor sem medicamentos é possível para muitos — exige método e paciência, não sorte."},{"type":"heading","level":2,"text":"Continue no Clube Saúde & Bem"},{"type":"paragraph","html":"<p>Quer protocolos premium, biblioteca ampliada e acompanhamento contínuo? O <strong>Clube Saúde &amp; Bem</strong> reúne ferramentas avançadas e conteúdo exclusivo para acelerar sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'sono', 'Sono', 'Dra. Marina Alves', 'Medicina Preventiva', '10 min', '19 Jun 2026', false, false, '/blog/categories/sono.svg', 'Como dormir melhor sem medicamentos | Guia Saúde & Bem', 'Higiene do sono, luz, temperatura e rotina comportamental — estratégias não farmacológicas com evidência.', 'dormir, melhor, sem, medicamentos, sono, saúde, bem-estar, saúde e bem', '/blog/categories/sono.svg', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a7100001-0001-4001-8001-000000000020', 'longevidade-qualidade-vida', 'Longevidade e qualidade de vida', 'Viver mais com vitalidade: movimento, nutrição, sono, conexões sociais e prevenção — os pilares com maior evidência.', '[{"type":"image","url":"/blog/categories/longevidade.svg","alt":"Capa: Longevidade e qualidade de vida"},{"type":"heading","level":2,"text":"Introdução"},{"type":"paragraph","text":"Longevidade não é apenas anos na vida — é vida nos anos. Populações com maior expectativa de vida saudável compartilham hábitos integrados, não segredos isolados."},{"type":"paragraph","text":"Prevenção começa décadas antes dos sintomas — cada escolha diária conta no acumulado."},{"type":"heading","level":2,"text":"Benefícios"},{"type":"list","items":["Mais anos com independência funcional","Menor risco de doenças crônicas","Vitalidade e propósito sustentados","Melhor qualidade de relações e cognição"]},{"type":"heading","level":2,"text":"Como aplicar"},{"type":"list","items":["Movimento diário + força 2–3x/semana.","Dieta rica em vegetais, proteínas magras e gorduras boas.","Sono regular e gestão de estresse.","Conexão social ativa e propósito.","Check-ups preventivos e exames conforme idade."],"ordered":true},{"type":"heading","level":2,"text":"Erros comuns"},{"type":"list","items":["Buscar ''hacks'' em detrimento dos pilares básicos","Negligenciar saúde mental na equação","Sedentarismo compensado só no fim de semana","Ignorar histórico familiar sem acompanhamento"]},{"type":"heading","level":2,"text":"Perguntas frequentes"},{"type":"faq","items":[{"question":"Genética determina tudo?","answer":"Influencia, mas estilo de vida modifica expressão de riscos em grande medida."},{"question":"Qual idade começar?","answer":"Agora. Benefícios existem em qualquer fase da vida."},{"question":"Suplementos anti-aging?","answer":"Evidência limitada para a maioria. Pilares básicos superam promessas de marketing."}]},{"type":"heading","level":2,"text":"Conclusão"},{"type":"paragraph","text":"Longevidade com qualidade é projeto de décadas feito em escolhas diárias pequenas — comece hoje com um pilar."},{"type":"heading","level":2,"text":"Continue no Clube Saúde & Bem"},{"type":"paragraph","html":"<p>Quer protocolos premium, biblioteca ampliada e acompanhamento contínuo? O <strong>Clube Saúde &amp; Bem</strong> reúne ferramentas avançadas e conteúdo exclusivo para acelerar sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'longevidade', 'Longevidade', 'Dr. Rafael Costa', 'Nutrição Clínica', '10 min', '20 Jun 2026', true, false, '/blog/categories/longevidade.svg', 'Longevidade e qualidade de vida | Guia Saúde & Bem', 'Viver mais com vitalidade: movimento, nutrição, sono, conexões sociais e prevenção — os pilares com maior evidência.', 'longevidade, qualidade, vida, longevidade, saúde, bem-estar, saúde e bem', '/blog/categories/longevidade.svg', 'published');
